/**
 * Apply pending SQL migrations from ./drizzle. Safe to run repeatedly; only
 * additive migrations are generated by default. Never point this at
 * production without a backup — see docs/deployment.md.
 */
import "../lib/load-env";
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";

const url = process.env.DATABASE_URL ?? "postgres://sweets@127.0.0.1:54329/sweets";
const client = postgres(url, { max: 1, onnotice: () => {} });
await migrate(drizzle(client), { migrationsFolder: "./drizzle" });
await client.end();
console.log(`Migrations applied to ${url.replace(/\/\/[^@]*@/, "//***@")}`);
